+    await fs.mkdir(path.dirname(destination), { recursive: true });
+    await fs.writeFile(destination, pageDocument(page), 'utf8');
+  }));
+  await fs.writeFile(path.join(outputDir, 'index.html'), indexDocument(pages), 'utf8');
+  return pages;
